    $BrandMark.Size = New-Object System.Drawing.Size(48, 48)
    $BrandMark.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
    $BrandMark.BackColor = [System.Drawing.Color]::FromArgb(25, 45, 70)
    $IconBase64 = ""
